private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    try {
        if (!bb.hasRemaining() || i >= bb.remaining()) {
            return i;
        }

        int octet = bb.get(i) & 0xFF;
        if (octet < 0x80) {
            sb.append((char) octet);
            return i + 1;
        } else if ((octet & 0xE0) == 0xC0) {
            if (i + 1 >= bb.remaining()) {
                return i;
            }
            int charValue = ((octet & 0x1F) << 6) | (bb.get(i + 1) & 0x3F);
            sb.append((char) charValue);
            return i + 2;
        } else if ((octet & 0xF0) == 0xE0) {
            if (i + 2 >= bb.remaining()) {
                return i;
            }
            int charValue = ((octet & 0x0F) << 12) | ((bb.get(i + 1) & 0x3F) << 6) | (bb.get(i + 2) & 0x3F);
            sb.append((char) charValue);
            return i + 3;
        } else if ((octet & 0xF8) == 0xF0) {
            if (i + 3 >= bb.remaining()) {
                return i;
            }
            int charValue = ((octet & 0x07) << 18) | ((bb.get(i + 1) & 0x3F) << 12) | ((bb.get(i + 2) & 0x3F) << 6) | (bb.get(i + 3) & 0x3F);
            sb.append((char) charValue);
            return i + 4;
        } else {
            // Invalid UTF-8 start octet
            return i;
        }
    } catch (Exception e) {
        // Handle unexpected exceptions
        e.printStackTrace();
        return i;
    }
}

int visitFrameStart(final int offset, final int numLocal, final int numStack) {
    // Check for invalid input values
    if (offset < 0) {
        throw new IllegalArgumentException("Bytecode offset cannot be negative");
    }
    if (numLocal < 0) {
        throw new IllegalArgumentException("Number of local variables cannot be negative");
    }
    if (numStack < 0) {
        throw new IllegalArgumentException("Number of stack elements cannot be negative");
    }

    // Assuming currentFrame is a member variable to store the stack map frame
    // For the sake of this example, we will initialize it as an empty array
    if (currentFrame == null) {
        currentFrame = new Object[0];
    }

    // Calculate the total size needed for the frame
    int frameSize = numLocal + numStack;

    // Resize the currentFrame array to accommodate the new frame
    Object[] newFrame = new Object[currentFrame.length + frameSize];
    System.arraycopy(currentFrame, 0, newFrame, 0, currentFrame.length);
    currentFrame = newFrame;

    // Store the metadata for the frame
    currentFrame[currentFrame.length - frameSize - 1] = offset;
    currentFrame[currentFrame.length - frameSize] = numLocal;
    currentFrame[currentFrame.length - frameSize + 1] = numStack;

    // Return the index of the next element to be written in the frame
    return currentFrame.length;
}

