protected List<TimeRange> buildTimeRanges(long start, long end) {
    final long FETCH_DATA_DURATION = 3600000L; // 1 hour in milliseconds

    if (start >= end) {
        throw new IllegalArgumentException("Start time must be before end time");
    }

    List<TimeRange> timeRanges = new ArrayList<>();

    while (start < end) {
        long currentEnd = Math.min(start + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(start, currentEnd));
        start = currentEnd;
    }

    return timeRanges;
}

