static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        // Convert the time bucket to a string in the format YYYYMMDD
        String timeStr = String.format("%08d", timeBucket);

        // Extract the year, month, and day as integers
        int year = Integer.parseInt(timeStr.substring(0, 4));
        int month = Integer.parseInt(timeStr.substring(4, 6));
        int day = Integer.parseInt(timeStr.substring(6, 8));

        // Adjust the day based on the dayStep
        if (dayStep == 0) {
            // If dayStep is 0, do not adjust the day
            day = day;
        } else if (dayStep == -1) {
            // If dayStep is -1, set the day to the first day of the month
            day = 1;
        } else if (dayStep == 1) {
            // If dayStep is 1, set the day to the last day of the month
            day = 28; // Simplified logic, assume month is not February
        }

        // Calculate the new year, month, and adjusted day
        int newYear = year;
        int newMonth = month;
        int newDay = day;

        // Adjust month and year if necessary
        if (newDay > 31) {
            newDay = 31;
            newMonth++;
        }
        if (newMonth > 12) {
            newMonth = 1;
            newYear++;
        }

        // Combine the new year, month, and day into a new time bucket
        return (long) newYear * 10000 + newMonth * 100 + newDay;
    } catch (Exception e) {
        // Handle unexpected errors
        e.printStackTrace();
        return -1; // Return -1 to indicate failure
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length");
    }

    int size = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(index + i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c) && i + 1 < len && Character.isLowSurrogate(str.charAt(index + i + 1))) {
            size += 4;
            i++; // Skip the low surrogate
        } else {
            size += 3;
        }
    }
    return size;
}

