public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and props must not be null");
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    while (value.contains("${")) {
        int start = value.indexOf("${");
        int end = value.indexOf('}', start);
        if (end == -1) {
            break; // Invalid format, break out of loop
        }

        String substKey = value.substring(start + 2, end);
        String substValue = props.getProperty(substKey);
        if (substValue == null) {
            break; // Substitution key not found, break out of loop
        }

        value = value.substring(0, start) + substValue + value.substring(end + 1);
    }

    return value;
}

