private void putAbstractTypes(final int start, final int end) {
    if (start < 0 || end > currentFrame.types.length || start >= end) {
        throw new IllegalArgumentException("Invalid start or end index");
    }

    for (int i = start; i < end; i++) {
        StackMapFrame.TypeInfo typeInfo = currentFrame.types[i];
        switch (typeInfo.tag) {
            case StackMapFrame.TypeInfo.UNINITIALIZED_THIS:
                stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntry.UNINITIALIZED_THIS));
                break;
            case StackMapFrame.TypeInfo.UNINITIALIZED:
                stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntry.UNINITIALIZED, ((StackMapFrame.UninitializedTypeInfo) typeInfo).offset));
                break;
            case StackMapFrame.TypeInfo.OBJECT:
                stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntry.OBJECT, ((StackMapFrame.ObjectTypeInfo) typeInfo).internalName));
                break;
            case StackMapFrame.TypeInfo.INT:
                stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntry.INT));
                break;
            case StackMapFrame.TypeInfo.FLOAT:
                stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntry.FLOAT));
                break;
            case StackMapFrame.TypeInfo.LONG:
                stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntry.LONG));
                break;
            case StackMapFrame.TypeInfo.DOUBLE:
                stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntry.DOUBLE));
                break;
            case StackMapFrame.TypeInfo.NULL:
                stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntry.NULL));
                break;
            case StackMapFrame.TypeInfo.METHOD_TYPE:
                stackMapTableEntries.add(new StackMapTableEntry(StackMapTableEntry.METHOD_TYPE, ((StackMapFrame.MethodTypeInfo) typeInfo).referenceIndex));
                break;
            case StackMapFrame.TypeInfo.METHOD_HANDLE:
                StackMapTable.MethodHandleEntry methodHandleEntry = new StackMapTableEntry.StackMapTableMethodHandleEntry();
                methodHandleEntry.referenceKind = ((StackMapFrame.MethodHandleTypeInfo) typeInfo).referenceKind;
                methodHandleEntry.referenceIndex = ((StackMapFrame.MethodHandleTypeInfo) typeInfo).referenceIndex;
                stackMapTableEntries.add(methodHandleEntry);
                break;
            default:
                throw new IllegalArgumentException("Unsupported type in currentFrame");
        }
    }
}

