        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i + 1 < str.length()) {
                char nextCh = str.charAt(i + 1);
                switch (nextCh) {
                    case 'b':
                        sb.append('\b');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case '"':
                        sb.append('"');
                        break;
                    case '\'':
                        sb.append '\'');
                        break;
                    case '\\':
                        sb.append('\\');
                        break;
                    default:
                        sb.append('\\');
                        sb.append(nextCh);
                        break;
                }
                i++;
