    if (bucketsByLabel.size() <= minLabel) {
        throw new IllegalArgumentException("Invalid bucket index: " + minLabel);
    }

    // Get the bucket with the label minLabel
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);

    // Check if the bucket is empty
    if (minBucket.isEmpty()) {
        return; // No need to do anything if the bucket is empty
    }

    // Move all vertices from the minLabel bucket to bucket 0
    bucketsByLabel.get(0).addAll(minBucket);

    // Clear the minLabel bucket
    minBucket.clear();

    // Update the labels of the vertices moved to bucket 0
    for (Integer vertex : bucketsByLabel.get(0)) {
        labels.set(vertex, 0);
    }
}

