public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> sequenceRanges = new ArrayList<>();
    // Step 1: Retrieve the current profiles segment snapshots
    List<Snapshot> snapshots = getCurrentProfilesSegmentSnapshots();

    // Step 2: Check if there are any snapshots to process
    if (snapshots.isEmpty()) {
        return sequenceRanges;
    }

    // Step 3: Sort the snapshots based on their sequence numbers
    snapshots.sort(Comparator.comparingLong(Snapshot::getSequenceNumber));

    // Step 4: Iterate through the sorted snapshots to build the sequence ranges
    for (int i = 0; i < snapshots.size() - 1; i++) {
        long startSequenceNumber = snapshots.get(i).getSequenceNumber();
        long endSequenceNumber = snapshots.get(i + 1).getSequenceNumber();

        // Step 5: Calculate the gap between the current and next snapshot
        long gap = endSequenceNumber - startSequenceNumber;

        // Step 6: If there is a gap, add the sequence range to the list
        if (gap > 0) {
            sequenceRanges.add(new SequenceRange(startSequenceNumber, endSequenceNumber));
        }
    }

    return sequenceRanges;
}

