private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<Integer, E> graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    for (Edge<E> edge : graph.getEdges()) {
        List<Pair<Integer, Integer>> minSeparators = new ArrayList<>();
        Set<Integer> endpoints = new HashSet<>();
        endpoints.add(edge.getSource());
        endpoints.add(edge.getDestination());

        for (Integer vertex : graph.getVertices()) {
            if (!endpoints.contains(vertex)) {
                Set<Integer> neighbors = graph.getNeighbors(vertex);
                if (Collections.disjoint(neighbors, endpoints)) {
                    minSeparators.add(new Pair<>(neighbors, edge.getElement()));
                }
            }
        }

        globalSeparatorList.add(new Pair<>(minSeparators, edge.getElement()));
    }

    return globalSeparatorList;
}

