private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices == null || vertices.isEmpty()) {
        return true; // An empty subgraph is trivially a clique
    }

    Set<V> expandedVertices = new HashSet<>(vertices);

    for (V vertex : vertices) {
        if (!expandedVertices.remove(vertex)) {
            throw new IllegalArgumentException("Vertices set contains duplicate elements");
        }

        for (V neighbor : graph.neighbors(vertex)) {
            if (!vertices.contains(neighbor)) {
                return false; // The subgraph is not complete if there is a neighbor not in the given vertices
            }
            if (!expandedVertices.contains(neighbor)) {
                expandedVertices.add(neighbor); // Add unvisited neighbors to be checked
            }
        }
    }

    return true;
}

