    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("Input list of keys cannot be null or empty.");
    }

    List<Integer> lowerBounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++) {
        int key = keys.get(i);
        int lowerBound = key;
        for (int j = i + 1; j < keys.size(); j++) {
            int nextKey = keys.get(j);
            if (nextKey < lowerBound) {
                lowerBound = nextKey;
            }
        }
        lowerBounds.add(lowerBound);
    }

    return lowerBounds;
}

