public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativeComponents = relativePath.split("/");

    // Apply the relative path components
    StringBuilder newPath = new StringBuilder();
    for (String comp : relativeComponents) {
        if (comp.equals("..")) {
            if (pathComponents.length > 1) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else if (!comp.isEmpty()) {
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            pathComponents[pathComponents.length - 1] = comp;
        }
    }

    // Reconstruct the path
    for (String comp : pathComponents) {
        newPath.append("/");
        newPath.append(comp);
    }

    // Handle leading slash if relativePath starts with ".."
    if (relativePath.startsWith("..")) {
        newPath.insert(0, "/");
    }

    return newPath.toString();
}

