public int readTag() throws IOException {
    int firstByte = in.read();
    if (firstByte == -1) {
        return 0; // EOF
    }
    int tag = 0;
    tag = tag << 7 | (firstByte & 0x7F);
    if ((firstByte & 0x80) == 0) {
        return tag;
    }
    int shift = 7;
    while ((firstByte & 0x80) != 0) {
        if (shift >= 32) {
            throw new IOException("Protocol message contained a tag with a wire type that is reserved");
        }
        firstByte = in.read();
        if (firstByte == -1) {
            throw new IOException("Came across the end of the stream while reading a tag");
        }
        tag = tag << 7 | (firstByte & 0x7F);
        shift += 7;
    }
    return tag;
}

